def lattice_matches(g, target, vals=None):
 ans=[]
 for r in range(3):
  for c in range(3):
   for dr in [2,3]:
    for dc in [2,3]:
     # starting at offsets, step, ensure fit
     if r+2*dr>=7 or c+2*dc>=7: continue
     a=[[g[r+i*dr][c+j*dc] for j in range(3)] for i in range(3)]
     mask=[[int(v in vals) for v in row] for row in a] if vals else a
     if mask==target: ans.append((r,c,dr,dc,a))
 return ans
